// Package codebuddy implements the Agent interface for CodeBuddy.
// CodeBuddy uses the same hook format as Claude Code, so this implementation
// reuses Claude Code's transcript parsing and hook logic.
package codebuddy

import (
	"bufio"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"regexp"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/transcript"
)

//nolint:gochecknoinits // Agent self-registration is the intended pattern
func init() {
	agent.Register(agent.AgentNameCodeBuddy, NewCodeBuddyAgent)
}

// CodeBuddyAgent implements the Agent interface for CodeBuddy.
//
//nolint:revive // CodeBuddyAgent is clearer than Agent in this context
type CodeBuddyAgent struct{}

// NewCodeBuddyAgent creates a new CodeBuddy agent instance.
func NewCodeBuddyAgent() agent.Agent {
	return &CodeBuddyAgent{}
}

// Name returns the agent registry key.
func (c *CodeBuddyAgent) Name() types.AgentName {
	return agent.AgentNameCodeBuddy
}

// Type returns the agent type identifier.
func (c *CodeBuddyAgent) Type() types.AgentType {
	return agent.AgentTypeCodeBuddy
}

// Description returns a human-readable description.
func (c *CodeBuddyAgent) Description() string {
	return "CodeBuddy - Tencent's AI coding assistant"
}

// IsPreview returns whether the agent integration is in preview.
func (c *CodeBuddyAgent) IsPreview() bool { return false }

// DetectPresence checks if CodeBuddy is configured in the repository.
func (c *CodeBuddyAgent) DetectPresence(ctx context.Context) (bool, error) {
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		repoRoot = "."
	}

	// Check for .codebuddy directory
	codeBuddyDir := filepath.Join(repoRoot, ".codebuddy")
	if _, err := os.Stat(codeBuddyDir); err == nil {
		return true, nil
	}
	// Check for .codebuddy/settings.json
	settingsFile := filepath.Join(repoRoot, ".codebuddy", "settings.json")
	if _, err := os.Stat(settingsFile); err == nil {
		return true, nil
	}
	return false, nil
}

// GetSessionID extracts the session ID from hook input.
func (c *CodeBuddyAgent) GetSessionID(input *agent.HookInput) string {
	return input.SessionID
}

// ResolveSessionFile returns the path to a CodeBuddy session file.
func (c *CodeBuddyAgent) ResolveSessionFile(sessionDir, agentSessionID string) string {
	return filepath.Join(sessionDir, agentSessionID+".jsonl")
}

// ProtectedDirs returns directories that CodeBuddy uses for config/state.
func (c *CodeBuddyAgent) ProtectedDirs() []string { return []string{".codebuddy"} }

// GetSessionDir returns the directory where CodeBuddy stores session transcripts.
func (c *CodeBuddyAgent) GetSessionDir(repoPath string) (string, error) {
	// Check for test environment override
	if override := os.Getenv("ENTIRE_TEST_CODEBUDDY_PROJECT_DIR"); override != "" {
		return override, nil
	}

	homeDir, err := os.UserHomeDir()
	if err != nil {
		return "", fmt.Errorf("failed to get home directory: %w", err)
	}

	projectDir := sanitizeRepoPath(repoPath)
	return filepath.Join(homeDir, ".codebuddy", "projects", projectDir), nil
}

// ReadSession reads a session from CodeBuddy's storage (JSONL transcript file).
func (c *CodeBuddyAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
	if input.SessionRef == "" {
		return nil, errors.New("session reference (transcript path) is required")
	}

	data, err := os.ReadFile(input.SessionRef) //nolint:gosec // Path comes from agent hook input
	if err != nil {
		return nil, fmt.Errorf("failed to read transcript: %w", err)
	}

	lines, err := transcript.ParseFromBytes(data)
	if err != nil {
		return nil, fmt.Errorf("failed to parse transcript: %w", err)
	}

	return &agent.AgentSession{
		SessionID:     input.SessionID,
		AgentName:     c.Name(),
		SessionRef:    input.SessionRef,
		StartTime:     time.Now(),
		NativeData:    data,
		ModifiedFiles: extractModifiedFiles(lines),
	}, nil
}

// WriteSession writes a session to CodeBuddy's storage (JSONL transcript file).
func (c *CodeBuddyAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
	if session == nil {
		return errors.New("session is nil")
	}

	if session.AgentName != "" && session.AgentName != c.Name() {
		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, c.Name())
	}

	if session.SessionRef == "" {
		return errors.New("session reference (transcript path) is required")
	}

	if len(session.NativeData) == 0 {
		return errors.New("session has no native data to write")
	}

	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
		return fmt.Errorf("failed to write transcript: %w", err)
	}

	return nil
}

// FormatResumeCommand returns the command to resume a CodeBuddy session.
func (c *CodeBuddyAgent) FormatResumeCommand(sessionID string) string {
	return "codebuddy -r " + sessionID
}

// GetTranscriptPosition returns the current line count of a CodeBuddy transcript.
func (c *CodeBuddyAgent) GetTranscriptPosition(path string) (int, error) {
	if path == "" {
		return 0, nil
	}

	file, err := os.Open(path) //nolint:gosec // Path comes from agent hook input
	if err != nil {
		if os.IsNotExist(err) {
			return 0, nil
		}
		return 0, fmt.Errorf("failed to open transcript file: %w", err)
	}
	defer file.Close()

	reader := bufio.NewReader(file)
	lineCount := 0

	for {
		line, err := reader.ReadBytes('\n')
		if err != nil {
			if err == io.EOF {
				if len(line) > 0 {
					lineCount++
				}
				break
			}
			return 0, fmt.Errorf("failed to read transcript: %w", err)
		}
		lineCount++
	}

	return lineCount, nil
}

// ExtractModifiedFilesFromOffset extracts files modified since a given line number.
func (c *CodeBuddyAgent) ExtractModifiedFilesFromOffset(path string, startOffset int) (files []string, currentPosition int, err error) {
	if path == "" {
		return nil, 0, nil
	}

	file, openErr := os.Open(path) //nolint:gosec // Path comes from agent hook input
	if openErr != nil {
		return nil, 0, fmt.Errorf("failed to open transcript file: %w", openErr)
	}
	defer file.Close()

	reader := bufio.NewReader(file)
	var lines []transcript.Line
	lineNum := 0

	for {
		lineData, readErr := reader.ReadBytes('\n')
		if readErr != nil && readErr != io.EOF {
			return nil, 0, fmt.Errorf("failed to read transcript: %w", readErr)
		}

		if len(lineData) > 0 {
			lineNum++
			if lineNum > startOffset {
				var line transcript.Line
				if parseErr := json.Unmarshal(lineData, &line); parseErr == nil {
					lines = append(lines, line)
				}
			}
		}

		if readErr == io.EOF {
			break
		}
	}

	return extractModifiedFiles(lines), lineNum, nil
}

// ChunkTranscript splits a JSONL transcript at line boundaries.
func (c *CodeBuddyAgent) ChunkTranscript(_ context.Context, content []byte, maxSize int) ([][]byte, error) {
	chunks, err := agent.ChunkJSONL(content, maxSize)
	if err != nil {
		return nil, fmt.Errorf("failed to chunk JSONL transcript: %w", err)
	}
	return chunks, nil
}

// ReassembleTranscript concatenates JSONL chunks with newlines.
func (c *CodeBuddyAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
	return agent.ReassembleJSONL(chunks), nil
}

// ReadSessionFromPath is a convenience method that reads a session directly from a file path.
func (c *CodeBuddyAgent) ReadSessionFromPath(transcriptPath, sessionID string) (*agent.AgentSession, error) {
	return c.ReadSession(&agent.HookInput{
		SessionID:  sessionID,
		SessionRef: transcriptPath,
	})
}

// sanitizeRepoPath converts a path to CodeBuddy's project directory format.
// CodeBuddy uses the same path sanitization as Claude Code (replace non-alphanumeric with dash).
var nonAlphanumericRegex = regexp.MustCompile(`[^a-zA-Z0-9]`)

func sanitizeRepoPath(path string) string {
	return nonAlphanumericRegex.ReplaceAllString(path, "-")
}

