    25→// WriteHookResponse outputs a JSON hook response to stdout.
    26→// CodeBuddy uses the same JSON systemMessage protocol as Claude Code.
    27→func (c *CodeBuddyAgent) WriteHookResponse(message string) error {
    28→	resp := struct {
    29→		SystemMessage string `json:"systemMessage,omitempty"`
    30→	}{SystemMessage: message}
    31→	if err := json.NewEncoder(os.Stdout).Encode(resp); err != nil {
    32→		return fmt.Errorf("failed to encode hook response: %w", err)
    33→	}
    34→	return nil
    35→}
    36→
    37→// HookNames returns the hook verbs CodeBuddy supports.
    38→// These become subcommands: entire hooks codebuddy <verb>
    39→func (c *CodeBuddyAgent) HookNames() []string {
    40→	return []string{
    41→		HookNameSessionStart,
    42→		HookNameSessionEnd,
    43→		HookNameStop,
    44→		HookNameUserPromptSubmit,
    45→		HookNamePreTask,
    46→		HookNamePostTask,
    47→		HookNamePostTodo,
    48→	}
    49→}
    50→
    51→// ParseHookEvent translates a CodeBuddy hook into a normalized lifecycle Event.
    52→// Returns nil if the hook has no lifecycle significance.
    53→func (c *CodeBuddyAgent) ParseHookEvent(_ context.Context, hookName string, stdin io.Reader) (*agent.Event, error) {
    54→	switch hookName {
    55→	case HookNameSessionStart:
    56→		return c.parseSessionStart(stdin)
    57→	case HookNameUserPromptSubmit:
    58→		return c.parseTurnStart(stdin)
    59→	case HookNameStop:
    60→		return c.parseTurnEnd(stdin)
    61→	case HookNameSessionEnd:
    62→		return c.parseSessionEnd(stdin)
    63→	case HookNamePreTask:
    64→		return c.parseSubagentStart(stdin)
    65→	case HookNamePostTask:
    66→		return c.parseSubagentEnd(stdin)
    67→	case HookNamePostTodo:
    68→		// PostTodo is handled outside the generic dispatcher (same as Claude Code).
    69→		return nil, nil //nolint:nilnil // nil event = no lifecycle action
    70→	default:
    71→		return nil, nil //nolint:nilnil // Unknown hooks have no lifecycle action
    72→	}
    73→}
    74→
    75→// ReadTranscript reads the raw JSONL transcript bytes for a session.
    76→func (c *CodeBuddyAgent) ReadTranscript(sessionRef string) ([]byte, error) {
    77→	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
    78→	if err != nil {
    79→		return nil, fmt.Errorf("failed to read transcript: %w", err)
    80→	}
    81→	return data, nil
    82→}
    83→
    84→// PrepareTranscript waits for CodeBuddy's async transcript flush to complete.
    85→func (c *CodeBuddyAgent) PrepareTranscript(ctx context.Context, sessionRef string) error {
    86→	waitForTranscriptFlush(ctx, sessionRef, time.Now())
    87→	return nil
    88→}
    89→
    90→// CalculateTokenUsage computes token usage from the transcript starting at the given line offset.
    91→func (c *CodeBuddyAgent) CalculateTokenUsage(transcriptData []byte, fromOffset int) (*agent.TokenUsage, error) {
    92→	if len(transcriptData) == 0 {
    93→		return &agent.TokenUsage{}, nil
    94→	}
    95→
    96→	sliced := transcript.SliceFromLine(transcriptData, fromOffset)
    97→	parsed, err := transcript.ParseFromBytes(sliced)
    98→	if err != nil {
    99→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
   100→	}
   101→
   102→	return calculateTokenUsage(parsed), nil
   103→}
   104→
   105→// --- Internal hook parsing functions ---
   106→
   107→func (c *CodeBuddyAgent) parseSessionStart(stdin io.Reader) (*agent.Event, error) {
   108→	raw, err := agent.ReadAndParseHookInput[sessionInfoRaw](stdin)
   109→	if err != nil {
   110→		return nil, err
   111→	}
   112→	return &agent.Event{
   113→		Type:       agent.SessionStart,
   114→		SessionID:  raw.SessionID,
   115→		SessionRef: raw.TranscriptPath,
   116→		Model:      raw.Model,
   117→		Timestamp:  time.Now(),
   118→	}, nil
