   112→		postTodoCmd = "go run ${CODEBUDDY_PROJECT_DIR}/cmd/entire/main.go hooks codebuddy post-todo"
   113→	} else {
   114→		sessionStartCmd = "entire hooks codebuddy session-start"
   115→		sessionEndCmd = "entire hooks codebuddy session-end"
   116→		stopCmd = "entire hooks codebuddy stop"
