   118→		preTaskCmd = "entire hooks codebuddy pre-task"
   119→		postTaskCmd = "entire hooks codebuddy post-task"
   120→		postTodoCmd = "entire hooks codebuddy post-todo"
   121→	}
   122→
   123→	count := 0
