   238→	settingsPath := filepath.Join(repoRoot, ".codebuddy", CodeBuddySettingsFileName)
   239→	data, err := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from repo root + fixed path
   240→	if err != nil {
   241→		return nil //nolint:nilerr // No settings file means nothing to uninstall
   242→	}
   243→
   244→	var rawSettings map[string]json.RawMessage
   245→	if err := json.Unmarshal(data, &rawSettings); err != nil {
   246→		return fmt.Errorf("failed to parse settings.json: %w", err)
   247→	}
   248→
   249→	var rawHooks map[string]json.RawMessage
   250→	if hooksRaw, ok := rawSettings["hooks"]; ok {
   251→		if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
   252→			return fmt.Errorf("failed to parse hooks: %w", err)
