   276→	marshalHookType(rawHooks, "Stop", stop)
   277→	marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
   278→	marshalHookType(rawHooks, "PreToolUse", preToolUse)
   279→	marshalHookType(rawHooks, "PostToolUse", postToolUse)
