   339→// AreHooksInstalled checks if Entire hooks are installed.
   340→func (c *CodeBuddyAgent) AreHooksInstalled(ctx context.Context) bool {
   341→	repoRoot, err := paths.WorktreeRoot(ctx)
   342→	if err != nil {
   343→		repoRoot = "."
   344→	}
   345→	settingsPath := filepath.Join(repoRoot, ".codebuddy", CodeBuddySettingsFileName)
   346→	data, err := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from repo root + fixed path
   347→	if err != nil {
   348→		return false
   349→	}
   350→
   351→	var settings CodeBuddySettings
   352→	if err := json.Unmarshal(data, &settings); err != nil {
   353→		return false
   354→	}
   355→
   356→	return hookCommandExists(settings.Hooks.Stop, "entire hooks codebuddy stop") ||
   357→		hookCommandExists(settings.Hooks.Stop, "go run ${CODEBUDDY_PROJECT_DIR}/cmd/entire/main.go hooks codebuddy stop")
   358→}
