   360→// Helper functions for hook management
   361→
   362→func hookCommandExists(matchers []CodeBuddyHookMatcher, command string) bool {
   363→	for _, matcher := range matchers {
   364→		for _, hook := range matcher.Hooks {
   365→			if hook.Command == command {
   366→				return true
   367→			}
   368→		}
   369→	}
   370→	return false
   371→}
   372→
   373→func hookCommandExistsWithMatcher(matchers []CodeBuddyHookMatcher, matcherName, command string) bool {
   374→	for _, matcher := range matchers {
   375→		if matcher.Matcher == matcherName {
   376→			for _, hook := range matcher.Hooks {
   377→				if hook.Command == command {
   378→					return true
   379→				}
   380→			}
   381→		}
   382→	}
   383→	return false
   384→}
   385→
   386→func addHookToMatcher(matchers []CodeBuddyHookMatcher, matcherName, command string) []CodeBuddyHookMatcher {
   387→	entry := CodeBuddyHookEntry{
   388→		Type:    "command",
   389→		Command: command,
   390→	}
   391→
   392→	if matcherName == "" {
   393→		for i, matcher := range matchers {
   394→			if matcher.Matcher == "" {
   395→				matchers[i].Hooks = append(matchers[i].Hooks, entry)
   396→				return matchers
   397→			}
   398→		}
   399→		return append(matchers, CodeBuddyHookMatcher{
   400→			Matcher: "",
   401→			Hooks:   []CodeBuddyHookEntry{entry},
   402→		})
   403→	}
   404→
   405→	for i, matcher := range matchers {
   406→		if matcher.Matcher == matcherName {
   407→			matchers[i].Hooks = append(matchers[i].Hooks, entry)
   408→			return matchers
   409→		}
   410→	}
   411→
   412→	return append(matchers, CodeBuddyHookMatcher{
   413→		Matcher: matcherName,
   414→		Hooks:   []CodeBuddyHookEntry{entry},
   415→	})
   416→}
   417→
   418→func isEntireHook(command string) bool {
   419→	for _, prefix := range entireHookPrefixes {
   420→		if strings.HasPrefix(command, prefix) {
   421→			return true
   422→		}
   423→	}
   424→	return false
   425→}
   426→
   427→func removeEntireHooks(matchers []CodeBuddyHookMatcher) []CodeBuddyHookMatcher {
   428→	result := make([]CodeBuddyHookMatcher, 0, len(matchers))
   429→	for _, matcher := range matchers {
   430→		filteredHooks := make([]CodeBuddyHookEntry, 0, len(matcher.Hooks))
   431→		for _, hook := range matcher.Hooks {
   432→			if !isEntireHook(hook.Command) {
   433→				filteredHooks = append(filteredHooks, hook)
   434→			}
   435→		}
   436→		if len(filteredHooks) > 0 {
   437→			matcher.Hooks = filteredHooks
   438→			result = append(result, matcher)
   439→		}
   440→	}
   441→	return result
   442→}
