   505→// TestCalculateTotalTokenUsage_PerCheckpoint verifies token usage
   506→// is calculated per-checkpoint, not from the full conversation.
   507→// This tests the core CalculateTotalTokenUsage function which should:
   508→// - From line 0: count all turns
   509→// - From line N: count only turns from line N onwards
   510→func TestCalculateTotalTokenUsage_PerCheckpoint(t *testing.T) {
   511→	t.Parallel()
   512→
   513→	// Build transcript with 3 turns:
   514→	// Turn 1: user + assistant (100 input, 50 output)
   515→	// Turn 2: user + assistant (200 input, 100 output)
   516→	// Turn 3: user + assistant (300 input, 150 output)
   517→	//
   518→	// Lines:
   519→	// 0: user message 1
   520→	// 1: assistant response 1 (100/50 tokens)
   521→	// 2: user message 2
   522→	// 3: assistant response 2 (200/100 tokens)
   523→	// 4: user message 3
   524→	// 5: assistant response 3 (300/150 tokens)
   525→
   526→	transcriptData := []byte(
   527→		`{"type":"user","uuid":"u1","message":{"content":"first prompt"}}` + "\n" +
   528→			`{"type":"assistant","uuid":"a1","message":{"id":"m1","usage":{"input_tokens":100,"output_tokens":50}}}` + "\n" +
   529→			`{"type":"user","uuid":"u2","message":{"content":"second prompt"}}` + "\n" +
   530→			`{"type":"assistant","uuid":"a2","message":{"id":"m2","usage":{"input_tokens":200,"output_tokens":100}}}` + "\n" +
   531→			`{"type":"user","uuid":"u3","message":{"content":"third prompt"}}` + "\n" +
   532→			`{"type":"assistant","uuid":"a3","message":{"id":"m3","usage":{"input_tokens":300,"output_tokens":150}}}` + "\n",
   533→	)
   534→
   535→	c := &ClaudeCodeAgent{}
   536→
   537→	// Test 1: From line 0 - all 3 turns = 600 input, 300 output
   538→	usage1, err := c.CalculateTotalTokenUsage(transcriptData, 0, "")
   539→	if err != nil {
   540→		t.Fatalf("CalculateTotalTokenUsage(0) error: %v", err)
   541→	}
   542→	if usage1.InputTokens != 600 || usage1.OutputTokens != 300 {
   543→		t.Errorf("From line 0: got input=%d output=%d, want input=600 output=300",
   544→			usage1.InputTokens, usage1.OutputTokens)
   545→	}
   546→	if usage1.APICallCount != 3 {
   547→		t.Errorf("From line 0: got APICallCount=%d, want 3", usage1.APICallCount)
   548→	}
   549→
   550→	// Test 2: From line 2 (after turn 1) - turns 2+3 only = 500 input, 250 output
   551→	usage2, err := c.CalculateTotalTokenUsage(transcriptData, 2, "")
   552→	if err != nil {
   553→		t.Fatalf("CalculateTotalTokenUsage(2) error: %v", err)
   554→	}
   555→	if usage2.InputTokens != 500 || usage2.OutputTokens != 250 {
   556→		t.Errorf("From line 2: got input=%d output=%d, want input=500 output=250",
   557→			usage2.InputTokens, usage2.OutputTokens)
   558→	}
   559→	if usage2.APICallCount != 2 {
   560→		t.Errorf("From line 2: got APICallCount=%d, want 2", usage2.APICallCount)
   561→	}
   562→
   563→	// Test 3: From line 4 (after turns 1+2) - turn 3 only = 300 input, 150 output
   564→	usage3, err := c.CalculateTotalTokenUsage(transcriptData, 4, "")
   565→	if err != nil {
   566→		t.Fatalf("CalculateTotalTokenUsage(4) error: %v", err)
   567→	}
   568→	if usage3.InputTokens != 300 || usage3.OutputTokens != 150 {
   569→		t.Errorf("From line 4: got input=%d output=%d, want input=300 output=150",
   570→			usage3.InputTokens, usage3.OutputTokens)
   571→	}
   572→	if usage3.APICallCount != 1 {
   573→		t.Errorf("From line 4: got APICallCount=%d, want 1", usage3.APICallCount)
   574→	}
   575→}
