package codebuddy

import (
	"context"
	"encoding/json"
	"os"
	"path/filepath"
	"slices"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/agent/testutil"
)

const metadataDenyRuleTest = "Read(./.entire/metadata/**)"

func TestInstallHooks_FreshInstall(t *testing.T) {
	tempDir := t.TempDir()
	t.Chdir(tempDir)

	ag := &CodeBuddyAgent{}
	count, err := ag.InstallHooks(context.Background(), false, false)
	if err != nil {
		t.Fatalf("InstallHooks() error = %v", err)
	}
	if count == 0 {
		t.Error("InstallHooks() should install at least one hook on fresh install")
	}

	// Verify settings file was created
	settingsPath := filepath.Join(tempDir, ".codebuddy", "settings.json")
	if _, err := os.Stat(settingsPath); os.IsNotExist(err) {
		t.Error("settings.json was not created")
	}
}

func TestInstallHooks_PermissionsDeny_FreshInstall(t *testing.T) {
	tempDir := t.TempDir()
	t.Chdir(tempDir)

	ag := &CodeBuddyAgent{}
	_, err := ag.InstallHooks(context.Background(), false, false)
	if err != nil {
		t.Fatalf("InstallHooks() error = %v", err)
	}

	perms := readCodeBuddyPermissions(t, tempDir)
	if !slices.Contains(perms.Deny, metadataDenyRuleTest) {
		t.Errorf("permissions.deny = %v, want to contain %q", perms.Deny, metadataDenyRuleTest)
	}
}

func TestInstallHooks_PermissionsDeny_Idempotent(t *testing.T) {
	tempDir := t.TempDir()
	t.Chdir(tempDir)

	ag := &CodeBuddyAgent{}
	_, err := ag.InstallHooks(context.Background(), false, false)
	if err != nil {
		t.Fatalf("first InstallHooks() error = %v", err)
	}

	_, err = ag.InstallHooks(context.Background(), false, false)
	if err != nil {
		t.Fatalf("second InstallHooks() error = %v", err)
	}

	perms := readCodeBuddyPermissions(t, tempDir)
	count := 0
	for _, rule := range perms.Deny {
		if rule == metadataDenyRuleTest {
			count++
		}
	}
	if count != 1 {
		t.Errorf("permissions.deny contains %d copies of rule, want exactly 1", count)
	}
}

func TestInstallHooks_PermissionsDeny_PreservesUserRules(t *testing.T) {
	tempDir := t.TempDir()
	t.Chdir(tempDir)

	writeCodeBuddySettingsFile(t, tempDir, `{
  "permissions": {
    "deny": ["Bash(rm -rf *)"]
  }
}`)

	ag := &CodeBuddyAgent{}
	_, err := ag.InstallHooks(context.Background(), false, false)
	if err != nil {
		t.Fatalf("InstallHooks() error = %v", err)
	}

	perms := readCodeBuddyPermissions(t, tempDir)
	if !slices.Contains(perms.Deny, "Bash(rm -rf *)") {
		t.Errorf("permissions.deny = %v, should still contain user rule", perms.Deny)
	}
	if !slices.Contains(perms.Deny, metadataDenyRuleTest) {
		t.Errorf("permissions.deny = %v, should contain Entire rule", perms.Deny)
	}
}

func TestInstallHooks_Idempotent_NoExtraHooks(t *testing.T) {
	tempDir := t.TempDir()
	t.Chdir(tempDir)

	ag := &CodeBuddyAgent{}
	_, err := ag.InstallHooks(context.Background(), false, false)
	if err != nil {
		t.Fatalf("first InstallHooks() error = %v", err)
	}

	count, err := ag.InstallHooks(context.Background(), false, false)
	if err != nil {
		t.Fatalf("second InstallHooks() error = %v", err)
	}
	if count != 0 {
		t.Errorf("second InstallHooks() count = %d, want 0 (already installed)", count)
	}
}

func TestInstallHooks_LocalDev(t *testing.T) {
	tempDir := t.TempDir()
	t.Chdir(tempDir)

	ag := &CodeBuddyAgent{}
	_, err := ag.InstallHooks(context.Background(), true, false)
	if err != nil {
		t.Fatalf("InstallHooks(localDev=true) error = %v", err)
	}

	rawHooks := testutil.ReadRawHooks(t, tempDir, ".codebuddy")

	// Check that the Stop hook uses the go run command
	var stopMatchers []CodeBuddyHookMatcher
	if err := json.Unmarshal(rawHooks["Stop"], &stopMatchers); err != nil {
		t.Fatalf("failed to parse Stop hooks: %v", err)
	}
	assertCodeBuddyHookExists(t, stopMatchers, "",
		"go run ${CODEBUDDY_PROJECT_DIR}/cmd/entire/main.go hooks codebuddy stop",
		"local dev Stop hook")
}

func TestInstallHooks_AllHookTypes(t *testing.T) {
	tempDir := t.TempDir()
	t.Chdir(tempDir)

	ag := &CodeBuddyAgent{}
	_, err := ag.InstallHooks(context.Background(), false, false)
	if err != nil {
		t.Fatalf("InstallHooks() error = %v", err)
	}

	rawHooks := testutil.ReadRawHooks(t, tempDir, ".codebuddy")

	expectedHookTypes := []string{"SessionStart", "SessionEnd", "Stop", "UserPromptSubmit", "PreToolUse", "PostToolUse"}
	for _, hookType := range expectedHookTypes {
		if _, ok := rawHooks[hookType]; !ok {
			t.Errorf("hook type %q was not installed", hookType)
		}
