func TestCalculateTokenUsage_ViaInterface(t *testing.T) {
	t.Parallel()

	transcriptData := []byte(
		`{"type":"user","uuid":"u1","message":{"content":"first prompt"}}` + "\n" +
			`{"type":"assistant","uuid":"a1","message":{"id":"m1","usage":{"input_tokens":100,"output_tokens":50}}}` + "\n" +
			`{"type":"user","uuid":"u2","message":{"content":"second prompt"}}` + "\n" +
			`{"type":"assistant","uuid":"a2","message":{"id":"m2","usage":{"input_tokens":200,"output_tokens":100}}}` + "\n",
	)

	ag := &CodeBuddyAgent{}

	// From line 0 - all turns
	usage1, err := ag.CalculateTokenUsage(transcriptData, 0)
	if err != nil {
		t.Fatalf("CalculateTokenUsage(0) error: %v", err)
	}
	if usage1.InputTokens != 300 || usage1.OutputTokens != 150 {
		t.Errorf("From line 0: got input=%d output=%d, want input=300 output=150",
			usage1.InputTokens, usage1.OutputTokens)
	}
	if usage1.APICallCount != 2 {
		t.Errorf("From line 0: got APICallCount=%d, want 2", usage1.APICallCount)
	}

	// From line 2 (after turn 1) - only turn 2
	usage2, err := ag.CalculateTokenUsage(transcriptData, 2)
	if err != nil {
		t.Fatalf("CalculateTokenUsage(2) error: %v", err)
	}
	if usage2.InputTokens != 200 || usage2.OutputTokens != 100 {
		t.Errorf("From line 2: got input=%d output=%d, want input=200 output=100",
			usage2.InputTokens, usage2.OutputTokens)
	}
	if usage2.APICallCount != 1 {
		t.Errorf("From line 2: got APICallCount=%d, want 1", usage2.APICallCount)
	}
}

func TestExtractModifiedFilesFromOffset(t *testing.T) {
	t.Parallel()

	tmpFile := filepath.Join(t.TempDir(), "transcript.jsonl")
	content := strings.Join([]string{
		`{"type":"assistant","uuid":"a1","message":{"content":[{"type":"tool_use","name":"Write","input":{"file_path":"early.go"}}]}}`,
		`{"type":"assistant","uuid":"a2","message":{"content":[{"type":"tool_use","name":"Write","input":{"file_path":"later.go"}}]}}`,
		`{"type":"assistant","uuid":"a3","message":{"content":[{"type":"tool_use","name":"Edit","input":{"file_path":"even-later.go"}}]}}`,
	}, "\n") + "\n"

	if err := os.WriteFile(tmpFile, []byte(content), 0o600); err != nil {
		t.Fatalf("failed to write: %v", err)
	}

	ag := &CodeBuddyAgent{}

	// From offset 0 - all files
	files0, pos0, err := ag.ExtractModifiedFilesFromOffset(tmpFile, 0)
	if err != nil {
		t.Fatalf("ExtractModifiedFilesFromOffset(0) error = %v", err)
	}
	if len(files0) != 3 {
		t.Errorf("From offset 0: got %d files, want 3", len(files0))
	}
	if pos0 != 3 {
		t.Errorf("From offset 0: position = %d, want 3", pos0)
	}

	// From offset 1 - skip first line
	files1, pos1, err := ag.ExtractModifiedFilesFromOffset(tmpFile, 1)
	if err != nil {
		t.Fatalf("ExtractModifiedFilesFromOffset(1) error = %v", err)
	}
	if len(files1) != 2 {
		t.Errorf("From offset 1: got %d files, want 2", len(files1))
	}
	if pos1 != 3 {
		t.Errorf("From offset 1: position = %d, want 3", pos1)
	}

	// early.go should NOT be in the result
	for _, f := range files1 {
		if f == "early.go" {
			t.Error("From offset 1: should not include early.go")
		}
	}
}

