func TestCheckStopSentinel_FoundSentinel(t *testing.T) {
	t.Parallel()

	tmpFile := filepath.Join(t.TempDir(), "transcript.jsonl")
	hookStartTime := nowFunc()
	sentinelEntry := map[string]string{
		"timestamp":     hookStartTime.Format("2006-01-02T15:04:05.999999999Z07:00"),
		"hook_progress": "entire hooks codebuddy stop in progress",
	}
	data, err := json.Marshal(sentinelEntry)
	if err != nil {
		t.Fatalf("failed to marshal sentinel: %v", err)
	}
	content := string(data) + "\n"
	if err := os.WriteFile(tmpFile, []byte(content), 0o600); err != nil {
		t.Fatalf("failed to write: %v", err)
	}

	found := checkStopSentinel(tmpFile, 4096, hookStartTime, 2)
	if !found {
		t.Error("checkStopSentinel() should find sentinel")
	}
}

// mustMarshalCodeBuddy is a test helper that marshals a value to JSON or fails the test.
func mustMarshalCodeBuddy(t *testing.T, v interface{}) []byte {
	t.Helper()
	data, err := json.Marshal(v)
	if err != nil {
		t.Fatalf("failed to marshal: %v", err)
	}
	return data
}

