		`{"type":"assistant","uuid":"a3","message":{"content":[{"type":"tool_use","name":"Edit","input":{"file_path":"even-later.go"}}]}}`,
	}, "\n") + "\n"

	if err := os.WriteFile(tmpFile, []byte(content), 0o600); err != nil {
		t.Fatalf("failed to write: %v", err)
	}

	ag := &CodeBuddyAgent{}

	// From offset 0 - all files
	files0, pos0, err := ag.ExtractModifiedFilesFromOffset(tmpFile, 0)
	if err != nil {
		t.Fatalf("ExtractModifiedFilesFromOffset(0) error = %v", err)
	}
	if len(files0) != 3 {
		t.Errorf("From offset 0: got %d files, want 3", len(files0))
	}
	if pos0 != 3 {
		t.Errorf("From offset 0: position = %d, want 3", pos0)
	}

	// From offset 1 - skip first line
	files1, pos1, err := ag.ExtractModifiedFilesFromOffset(tmpFile, 1)
	if err != nil {
		t.Fatalf("ExtractModifiedFilesFromOffset(1) error = %v", err)
	}
	if len(files1) != 2 {
		t.Errorf("From offset 1: got %d files, want 2", len(files1))
	}
	if pos1 != 3 {
		t.Errorf("From offset 1: position = %d, want 3", pos1)
	}

	for _, f := range files1 {
		if f == "early.go" {
			t.Error("From offset 1: should not include early.go")
		}
	}
}

