func TestCheckStopSentinel_FoundSentinel(t *testing.T) {
	t.Parallel()

	tmpFile := filepath.Join(t.TempDir(), "transcript.jsonl")
	hookStartTime := time.Now()
	sentinelEntry := map[string]string{
		"timestamp":     hookStartTime.Format(time.RFC3339Nano),
		"hook_progress": "entire hooks codebuddy stop in progress",
	}
	data, err := json.Marshal(sentinelEntry)
	if err != nil {
		t.Fatalf("failed to marshal sentinel: %v", err)
	}
	content := string(data) + "\n"
	if err := os.WriteFile(tmpFile, []byte(content), 0o600); err != nil {
		t.Fatalf("failed to write: %v", err)
	}

	found := checkStopSentinel(tmpFile, 4096, hookStartTime, 2*time.Second)
	if !found {
