	}
}

func TestCheckStopSentinel_NoSentinel(t *testing.T) {
	t.Parallel()

	tmpFile := filepath.Join(t.TempDir(), "transcript.jsonl")
	content := `{"type":"user","uuid":"u1"}` + "\n"
	if err := os.WriteFile(tmpFile, []byte(content), 0o600); err != nil {
