func TestCheckStopSentinel_OutsideTimeWindow(t *testing.T) {
	t.Parallel()

	tmpFile := filepath.Join(t.TempDir(), "transcript.jsonl")
	// Write a sentinel with a timestamp far in the past
	pastTime := time.Now().Add(-10 * time.Minute)
	sentinelEntry := map[string]string{
