func TestExtractModifiedFiles_WriteAndEdit(t *testing.T) {
	t.Parallel()

	data := []byte(
		`{"type":"assistant","uuid":"a1","message":{"content":[{"type":"tool_use","name":"Write","input":{"file_path":"foo.go"}}]}}` + "\n" +
			`{"type":"assistant","uuid":"a2","message":{"content":[{"type":"tool_use","name":"Edit","input":{"file_path":"bar.go"}}]}}` + "\n" +
			`{"type":"assistant","uuid":"a3","message":{"content":[{"type":"tool_use","name":"Bash","input":{"command":"ls"}}]}}` + "\n" +
			`{"type":"assistant","uuid":"a4","message":{"content":[{"type":"tool_use","name":"Write","input":{"file_path":"foo.go"}}]}}` + "\n",
	)

	lines, err := transcript.ParseFromBytes(data)
	if err != nil {
		t.Fatalf("ParseFromBytes() error = %v", err)
	}
	files := extractModifiedFiles(lines)

	// foo.go and bar.go (deduplicated, Bash not included)
	if len(files) != 2 {
		t.Errorf("extractModifiedFiles() got %d files, want 2", len(files))
	}

	hasFile := func(name string) bool {
		for _, f := range files {
			if f == name {
				return true
			}
		}
		return false
	}

	if !hasFile("foo.go") {
		t.Error("extractModifiedFiles() missing foo.go")
	}
	if !hasFile("bar.go") {
		t.Error("extractModifiedFiles() missing bar.go")
	}
}

