// Helper functions

type testCodeBuddyPermissions struct {
	Allow []string `json:"allow,omitempty"`
	Deny  []string `json:"deny,omitempty"`
}

func readCodeBuddyPermissions(t *testing.T, tempDir string) testCodeBuddyPermissions {
	t.Helper()
	settingsPath := filepath.Join(tempDir, ".codebuddy", "settings.json")
	data, err := os.ReadFile(settingsPath) //nolint:gosec // Test utility
	if err != nil {
		t.Fatalf("failed to read settings.json: %v", err)
	}

	var rawSettings map[string]json.RawMessage
	if err := json.Unmarshal(data, &rawSettings); err != nil {
		t.Fatalf("failed to parse settings.json: %v", err)
	}

	var perms testCodeBuddyPermissions
	if permRaw, ok := rawSettings["permissions"]; ok {
		if err := json.Unmarshal(permRaw, &perms); err != nil {
			t.Fatalf("failed to parse permissions: %v", err)
		}
	}
	return perms
}

func writeCodeBuddySettingsFile(t *testing.T, tempDir, content string) {
	t.Helper()
	dir := filepath.Join(tempDir, ".codebuddy")
	if err := os.MkdirAll(dir, 0o755); err != nil {
		t.Fatalf("failed to create .codebuddy dir: %v", err)
	}
	settingsPath := filepath.Join(dir, "settings.json")
	if err := os.WriteFile(settingsPath, []byte(content), 0o644); err != nil { //nolint:gosec // Test utility
		t.Fatalf("failed to write settings.json: %v", err)
	}
}

func readCodeBuddySettings(t *testing.T, tempDir string) CodeBuddySettings {
	t.Helper()
	settingsPath := filepath.Join(tempDir, ".codebuddy", "settings.json")
	data, err := os.ReadFile(settingsPath) //nolint:gosec // Test utility
	if err != nil {
		t.Fatalf("failed to read settings.json: %v", err)
	}

	var settings CodeBuddySettings
	if err := json.Unmarshal(data, &settings); err != nil {
		t.Fatalf("failed to parse settings.json: %v", err)
	}
	return settings
}

func assertCodeBuddyHookExists(t *testing.T, matchers []CodeBuddyHookMatcher, matcher, command, description string) {
	t.Helper()
	for _, m := range matchers {
		if m.Matcher == matcher {
			for _, h := range m.Hooks {
				if h.Command == command {
					return
				}
			}
		}
	}
	t.Errorf("%s was not found (matcher=%q, command=%q)", description, matcher, command)
}

