func TestGetSessionDir_SanitizesPath(t *testing.T) {
	// Cannot use t.Parallel() with t.Setenv
	t.Setenv("ENTIRE_TEST_CODEBUDDY_PROJECT_DIR", "")

	ag := &CodeBuddyAgent{}
	homeDir, err := os.UserHomeDir()
	if err != nil {
		t.Skip("cannot determine home directory")
	}

	dir, err := ag.GetSessionDir("/Users/foo/my-project")
	if err != nil {
		t.Fatalf("GetSessionDir() error = %v", err)
	}

	expected := filepath.Join(homeDir, ".codebuddy", "projects", "-Users-foo-my-project")
	if dir != expected {
		t.Errorf("GetSessionDir() = %q, want %q", dir, expected)
	}
}

func TestSanitizeRepoPath(t *testing.T) {
	t.Parallel()

	tests := []struct {
		input    string
		expected string
	}{
		{"/Users/foo/project", "-Users-foo-project"},
		{"/home/user/my project", "-home-user-my-project"},
		{"C:\\Users\\foo", "C--Users-foo"},
		{"simple", "simple"},
		{"/a/b/c", "-a-b-c"},
	}

	for _, tt := range tests {
		t.Run(tt.input, func(t *testing.T) {
			t.Parallel()
			result := sanitizeRepoPath(tt.input)
			if result != tt.expected {
				t.Errorf("sanitizeRepoPath(%q) = %q, want %q", tt.input, result, tt.expected)
			}
		})
	}
}

