func TestGetTranscriptPosition_CountsLines(t *testing.T) {
	t.Parallel()

	tmpFile := filepath.Join(t.TempDir(), "transcript.jsonl")
	content := `{"type":"user","uuid":"u1"}` + "\n" +
		`{"type":"assistant","uuid":"a1"}` + "\n" +
		`{"type":"user","uuid":"u2"}` + "\n"
	if err := os.WriteFile(tmpFile, []byte(content), 0o600); err != nil {
		t.Fatalf("failed to write: %v", err)
	}

	ag := &CodeBuddyAgent{}
	pos, err := ag.GetTranscriptPosition(tmpFile)
	if err != nil {
