func TestReadSession_ValidTranscript(t *testing.T) {
	t.Parallel()

	tmpFile := filepath.Join(t.TempDir(), "sess.jsonl")
	content := `{"type":"user","uuid":"u1","message":{"content":"hello"}}` + "\n" +
		`{"type":"assistant","uuid":"a1","message":{"content":[]}}` + "\n"
	if err := os.WriteFile(tmpFile, []byte(content), 0o600); err != nil {
		t.Fatalf("failed to write: %v", err)
	}

	ag := &CodeBuddyAgent{}
	session, err := ag.ReadSession(&agent.HookInput{
		SessionID:  "sess-abc",
		SessionRef: tmpFile,
	})
	if err != nil {
		t.Fatalf("ReadSession() error = %v", err)
	}
	if session == nil {
		t.Fatal("ReadSession() returned nil session")
	}
	if session.SessionID != "sess-abc" {
		t.Errorf("session.SessionID = %q, want %q", session.SessionID, "sess-abc")
	}
	if session.SessionRef != tmpFile {
		t.Errorf("session.SessionRef = %q, want %q", session.SessionRef, tmpFile)
	}
	if len(session.NativeData) == 0 {
		t.Error("session.NativeData should not be empty")
	}
}

